public static void writeDynamicTypeTag(OutputStream stream, ClickHouseColumn typeColumn)
            throws IOException {

        ClickHouseDataType dt = typeColumn.getDataType();

        if (typeColumn.isNullable()) {
            stream.write(ClickHouseDataType.NULLABLE_BIN_TAG);
        }
        if (typeColumn.isLowCardinality()) {
            stream.write(ClickHouseDataType.LOW_CARDINALITY_BIN_TAG);
        }

        byte binTag = dt.getBinTag();
        if (binTag == -1) {
            switch (dt) {
                case Point:
                case LineString:
                case MultiLineString:
                case MultiPoint:
                case Polygon:
                case Ring:
                case MultiPolygon:
                case Geometry:
                    stream.write(ClickHouseDataType.CUSTOM_TYPE_BIN_TAG);
                    BinaryStreamUtils.writeString(stream, dt.name());
                    return;
                default:
                    throw new ClientException("Type " + dt.name() +" serialization is not supported for Dynamic column");
            }
        }
        switch (dt) {
            case FixedString:
                stream.write(binTag);
                BinaryStreamUtils.writeVarInt(stream, typeColumn.getEstimatedLength());
                break;
            case Enum8:
            case Enum16:
                stream.write(binTag);
                ClickHouseEnum enumVal = typeColumn.getEnumConstants();
                String[] names = enumVal.getNames();
                int[] values = enumVal.getValues();
                BinaryStreamUtils.writeVarInt(stream, names.length);
                for (int i = 0; i < enumVal.size(); i++ ) {
                    BinaryStreamUtils.writeString(stream, names[i]);
                    if (dt == ClickHouseDataType.Enum8) {
                        BinaryStreamUtils.writeInt8(stream, values[i]);
                    } else {
                        BinaryStreamUtils.writeInt16(stream, values[i]);
                    }
                }
                break;
            case Decimal:
            case Decimal32:
            case Decimal64:
            case Decimal128:
            case Decimal256:
                stream.write(binTag);
                BinaryStreamUtils.writeUnsignedInt8(stream, dt.getMaxPrecision());
                BinaryStreamUtils.writeUnsignedInt8(stream, typeColumn.getScale());
                break;
            case IntervalNanosecond:
            case IntervalMillisecond:
            case IntervalSecond:
            case IntervalMinute:
            case IntervalHour:
            case IntervalDay:
            case IntervalWeek:
            case IntervalMonth:
            case IntervalQuarter:
            case IntervalYear:
                stream.write(binTag);
                Byte kindTag = ClickHouseDataType.intervalType2Kind.get(dt).getTag();
                if (kindTag == null) {
                    throw new ClientException("BUG! No Interval Mapping to a kind tag");
                }
                stream.write(kindTag);
                break;
            case DateTime32:
                stream.write(binTag);
                BinaryStreamUtils.writeString(stream, typeColumn.getTimeZoneOrDefault(TimeZone.getDefault()).getID());
                break;
            case DateTime64:
                stream.write(binTag);
                BinaryStreamUtils.writeUnsignedInt8(stream, typeColumn.getScale());
                BinaryStreamUtils.writeString(stream, typeColumn.getTimeZoneOrDefault(TimeZone.getDefault()).getID());
                break;
            case Array:
                stream.write(binTag);
                ClickHouseColumn arrayElemColumn = typeColumn.getNestedColumns().get(0);
                writeDynamicTypeTag(stream, arrayElemColumn);
                break;
            case Map:
                stream.write(binTag);
                // 0x27<key_type_encoding><value_type_encoding>
                writeDynamicTypeTag(stream, typeColumn.getKeyInfo());
                writeDynamicTypeTag(stream, typeColumn.getValueInfo());
                break;
            case Tuple:
                // Tuple(T1, ..., TN)
                //  0x1F<var_uint_number_of_elements><nested_type_encoding_1>...<nested_type_encoding_N>
                stream.write(0x1F);
                // or
                // Tuple(name1 T1, ..., nameN TN)
                //  0x20<var_uint_number_of_elements><var_uint_name_size_1><name_data_1><nested_type_encoding_1>...<var_uint_name_size_N><name_data_N><nested_type_encoding_N>
                stream.write(0x20);
                break;
            case Variant:
                stream.write(binTag);
                break;
            case Dynamic:
                stream.write(binTag);
                break;
            case JSON:
                stream.write(binTag);
                break;
            case SimpleAggregateFunction:
            case AggregateFunction:
                // A SimpleAggregateFunction inside a Dynamic column has to be encoded as
                // 0x2E <var_uint function_name_size> <function_name> <var_uint number_of_parameters>
                // <parameter_1>...<parameter_N> <var_uint number_of_arguments>
                // <argument_type_encoding_1>...<argument_type_encoding_N> (an AggregateFunction
                // additionally carries a var_uint version). The name and the argument types are what
                // identify the aggregate state, so a bare tag byte is not a valid encoding: the server
                // keeps reading the function name out of the bytes that follow, consuming the value and
                // desynchronizing the RowBinary stream (it fails with ATTEMPT_TO_READ_AFTER_EOF).
                // The client never infers either type from a Java value (valueToColumnForDynamicType
                // only yields Array/Map/scalar types) and BinaryStreamReader.readDynamicData cannot
                // read them back, so reject explicitly instead of emitting an unparseable tag.
                // AggregateFunction has no binary tag assigned yet and is already rejected above by
                // the binTag == -1 branch; it is grouped here so it stays rejected if one is added.
                throw new ClientException("Serializing a " + dt.name()
                        + " value inside a Dynamic column is not supported");
            case Time64:
                stream.write(binTag);
                BinaryStreamUtils.writeUnsignedInt8(stream, dt.getMaxPrecision());
                break;
            case QBit:
                // A QBit inside a Dynamic/Variant/JSON column would have to be encoded as
                // 0x36 <element_type_encoding> <var_uint dimension> to round-trip with
                // BinaryStreamReader.readDynamicData. The client never infers a QBit type from a
                // Java value (valueToColumnForDynamicType only yields Array/Map/scalar types), so
                // this path is unreachable through the public write API. Reject explicitly rather
                // than fall through to the default branch and emit a bare 0x36 tag that the reader
                // cannot parse and that would desynchronize the RowBinary stream. Reading a
                // server-sent QBit inside a Dynamic column IS supported (see
                // BinaryStreamReader.readDynamicData).
                throw new ClientException("Serializing a QBit value inside a Dynamic column is not supported");
            default:
                stream.write(binTag);
        }
    }

public static void serializeData(OutputStream stream, Object value, ClickHouseColumn column) throws IOException {
        //Serialize the value to the stream based on the data type
        switch (column.getDataType()) {
            case QBit:
                serializeQBitData(stream, value, column);
                break;
            case Array:
                serializeArrayData(stream, value, column);
                break;
            case Tuple:
                serializeTupleData(stream, value, column);
                break;
            case Map:
                serializeMapData(stream, value, column);
                break;
            case Nested:
                serializeNestedTypeData(stream, value, column);
                break;
            case SimpleAggregateFunction:
                // A SimpleAggregateFunction(func, T) value serializes identically to its underlying
                // type T. This is a deliberate exception to serializeNestedData's "nested elements
                // only" contract: the SAF wrapper is itself non-nullable, so writeValuePreamble emits
                // no null-marker for a top-level SAF column, yet a Nullable underlying still needs one.
                // serializeNestedData writes that marker iff the underlying is nullable, mirroring
                // BinaryStreamReader's read path.
                serializeNestedData(stream, value, column.getNestedColumns().get(0));
                break;
            case AggregateFunction:
                serializeAggregateFunction(stream, value, column);
                break;
            case Variant:
                serializerVariant(stream, column, value);
                break;
            case Geometry:
                serializerGeometry(stream, column, value);
                break;
            case Point:
                value = value instanceof ClickHouseGeoPointValue ? ((ClickHouseGeoPointValue)value).getValue() : value;
                serializeTupleData(stream, value, GEO_POINT_TUPLE);
                break;
            case Ring:
            case LineString:
            case MultiPoint:
                value = value instanceof ClickHouseGeoRingValue ? ((ClickHouseGeoRingValue)value).getValue() : value;
                serializeArrayData(stream, value, GEO_RING_ARRAY);
                break;
            case Polygon:
            case MultiLineString:
                value = value instanceof ClickHouseGeoPolygonValue ? ((ClickHouseGeoPolygonValue)value).getValue() : value;
                serializeArrayData(stream, value, GEO_POLYGON_ARRAY);
                break;
            case MultiPolygon:
                value = value instanceof ClickHouseGeoMultiPolygonValue ? ((ClickHouseGeoMultiPolygonValue)value).getValue() : value;
                serializeArrayData(stream, value, GEO_MULTI_POLYGON_ARRAY);
                break;
            case Dynamic:
                ClickHouseColumn typeColumn = valueToColumnForDynamicType(value);
                writeDynamicTypeTag(stream, typeColumn);
                serializeData(stream, value, typeColumn);
                break;
            default:
                serializePrimitiveData(stream, value, column);
                break;

        }
    }

public CompletableFuture<InsertResponse> insert(String tableName,
                                     List<String> columnNames,
                                     DataStreamWriter writer,
                                     ClickHouseFormat format,
                                     InsertSettings settings) {
        if (settings == null) {
            throw new  IllegalArgumentException("Settings cannot be null");
        }
        final InsertSettings requestSettings = new InsertSettings(buildRequestSettings(settings.getAllSettings()));
        requestSettings.setOption(ClientConfigProperties.INPUT_OUTPUT_FORMAT.getKey(), format);

        String operationId = requestSettings.getOperationId();
        ClientStatisticsHolder clientStats = null;
        if (operationId != null) {
            clientStats = globalClientStats.remove(operationId);
        }

        if (clientStats == null) {
            clientStats = new ClientStatisticsHolder();
        }
        // Origin of the duration of a failed operation. Taken where the client starts OP_DURATION, which is
        // the duration reported for a successful operation, so that both outcomes measure the same work.
        final long operationStartNanos = System.nanoTime();
        clientStats.start(ClientMetrics.OP_DURATION);
        final ClientStatisticsHolder finalClientStats = clientStats;



        final int writeBufferSize = requestSettings.getInputStreamCopyBufferSize() <= 0 ?
                (int) configuration.get(ClientConfigProperties.CLIENT_NETWORK_BUFFER_SIZE.getKey()) :
                requestSettings.getInputStreamCopyBufferSize();

        if (writeBufferSize <= 0) {
            throw new IllegalArgumentException("Buffer size must be greater than 0");
        }

        StringBuilder sqlStmt = new StringBuilder("INSERT INTO ").append(tableName);
        if (columnNames != null && !columnNames.isEmpty()) {
            sqlStmt.append(" (");
            for (String columnName : columnNames) {
                sqlStmt.append(columnName).append(", ");
            }
            sqlStmt.deleteCharAt(sqlStmt.length() - 2);
            sqlStmt.append(")");
        }
        sqlStmt.append(" FORMAT ").append(format.name());
        requestSettings.serverSetting(ClickHouseHttpProto.QPARAM_QUERY_STMT, sqlStmt.toString());
        if (requestSettings.getQueryId() == null && queryIdGenerator != null) {
            requestSettings.setQueryId(queryIdGenerator.get());
        }

        final int maxRetries = ClientConfigProperties.RETRY_ON_FAILURE.getOrDefault(requestSettings.getAllSettings());
        final int maxAttempts = Math.max(maxRetries, endpoints.size() - 1);
        final Span operationSpan = orNoop(spanRecorder.startInsertSpan(requestSettings, tableName,
                SpanRecorder.BATCH_SIZE_UNKNOWN, endpoints.get(0)));
        Supplier<InsertResponse> responseSupplier = () -> {
            long startTime = System.nanoTime();
            // Selecting some node
            Endpoint selectedEndpoint = nodeSelector.getEndpoint();

            RuntimeException lastException = null;
            final String queryId = requestSettings.getQueryId();
            try {
                for (int i = 0; i <= maxAttempts; i++) {
                    failIfCancelled(queryId, i, lastException);
                    // Execute request
                    TransportRequest transportRequest = httpClientHelper.createRequest(selectedEndpoint, requestSettings.getAllSettings(),
                            out -> {
                                writer.onOutput(out);
                                out.close();
                            });
                    registerTransportReq(queryId, transportRequest);

                    try (TransportResponse transportResponse = httpClientHelper.executeRequest(transportRequest, operationSpan)) {
                        OperationMetrics metrics = completeOperation(transportResponse, finalClientStats,
                                requestSettings.getQueryId(), OperationType.INSERT);
                        spanRecorder.recordInsertSuccess(operationSpan, metrics);
                        metricsRecorder.recordInsertSuccess(requestSettings, tableName, metrics);
                        return new InsertResponse(transportResponse, metrics);
                    } catch (Exception e) {
                        String msg = requestExMsg("Insert", (i + 1), durationSince(startTime).toMillis(), requestSettings.getQueryId());
                        lastException = httpClientHelper.wrapException(msg, e, requestSettings.getQueryId());
                        if (httpClientHelper.shouldRetry(e, requestSettings.getAllSettings()) && requestIsNotCancelled(requestSettings.getQueryId())) {
                            if (i < maxAttempts) {
                                metricsRecorder.recordInsertRetry(requestSettings, tableName, lastException);
                                selectedEndpoint = logRetryAndSelectNextNode("Insert (stream)", i, maxAttempts, requestSettings.getQueryId(), selectedEndpoint, e);
                            } else {
                                nodeSelector.getNextAliveNode(selectedEndpoint);
                            }
                        } else {
                            throw lastException;
                        }
                    }

                    if (i < maxAttempts) {
                        try {
                            writer.onRetry();
                        } catch (IOException ioe) {
                            throw new ClientException("Failed to reset stream before next attempt", ioe);
                        }
                    }
                }

                String errMsg = requestExMsg("Insert", maxAttempts + 1, durationSince(startTime).toMillis(), requestSettings.getQueryId());
                LOG.warn(errMsg);
                throw (lastException == null ? new ClientException(errMsg) : lastException);
            } catch (RuntimeException | Error e) {
                // Taken before any recorder runs, like the duration of a successful operation, which the
                // client stops in completeOperation.
                final Duration failureDuration = durationSince(operationStartNanos);
                spanRecorder.recordFailure(operationSpan, e);
                metricsRecorder.recordInsertFailure(requestSettings, tableName, failureDuration, e);
                throw e;
            } finally {
                // The request of the last attempt stays registered until the operation is over, so a cancellation
                // landing between two attempts is not lost.
                unregisterTransportReq(queryId);
                operationSpan.end();
            }
        };

        return runAsyncOperation(responseSupplier, requestSettings.getAllSettings());
    }

public static ClickHouseColumn valueToColumnForDynamicType(Object value) {
        ClickHouseColumn column;
        if (value instanceof ZonedDateTime) {
            ZonedDateTime dt = (ZonedDateTime) value;
            column = ClickHouseColumn.of("v", "DateTime64(9, " + dt.getZone().getId() + ")");
        } else if (value instanceof LocalDateTime) {
            column = ClickHouseColumn.of("v", "DateTime64(9, " + ZoneId.systemDefault().getId() + ")");
        } else if (value instanceof BigDecimal) {
            BigDecimal d = (BigDecimal) value;
            // A DecimalN(S) column is Decimal(P, S) with P fixed to the width's precision
            // (Decimal32=9, Decimal64=18, Decimal128=38, Decimal256=76) and 0 <= S <= P, so it can
            // hold at most P - S integer digits. Size the width to fit both the integer digits and
            // the value's own scale, then keep S as wide as the width allows without stealing room
            // from the integer part. Keying the width off precision() alone and forcing S to the
            // width maximum truncated values whose scale exceeded that maximum, and overflowed
            // values that carried an integer part.
            int valueScale = Math.max(d.scale(), 0);
            int integerDigits = Math.max(d.precision() - d.scale(), 0);
            int requiredPrecision = integerDigits + valueScale;
            if (requiredPrecision > ClickHouseDataType.Decimal256.getMaxPrecision()) {
                if (d.signum() != 0) {
                    throw new ClientException("Unable to serialize BigDecimal into a Dynamic column: it needs "
                            + requiredPrecision + " digits of precision, exceeding the maximum supported Decimal256 precision of "
                            + ClickHouseDataType.Decimal256.getMaxPrecision());
                }
                // A numerically-zero value rounds to zero at any scale with no data loss, so it fits
                // any Decimal width regardless of the scale/exponent implied by precision()/scale()
                // (e.g. 0E-77 implies scale 77, 0E+77 implies 78 integer digits). Store it in the
                // widest band rather than rejecting a value ClickHouse can represent exactly; cap the
                // integer digits so the emitted scale (maxScale - integerDigits) stays non-negative.
                integerDigits = Math.min(integerDigits, ClickHouseDataType.Decimal256.getMaxScale());
                requiredPrecision = ClickHouseDataType.Decimal256.getMaxPrecision();
            }
            ClickHouseDataType decType;
            if (requiredPrecision > ClickHouseDataType.Decimal128.getMaxPrecision()) {
                decType = ClickHouseDataType.Decimal256;
            } else if (requiredPrecision > ClickHouseDataType.Decimal64.getMaxPrecision()) {
                decType = ClickHouseDataType.Decimal128;
            } else if (requiredPrecision > ClickHouseDataType.Decimal32.getMaxPrecision()) {
                decType = ClickHouseDataType.Decimal64;
            } else {
                decType = ClickHouseDataType.Decimal32;
            }
            int scale = decType.getMaxScale() - integerDigits;

            column = ClickHouseColumn.of("v", decType.name() + "(" + scale + ")");
        } else if (value instanceof Map<?,?>) {
            Map<?, ?> map = (Map<?, ?>) value;
            // TODO: handle empty map?
            Map.Entry<?, ?> entry = map.entrySet().iterator().next();
            ClickHouseColumn keyInfo = valueToColumnForDynamicType(entry.getKey());
            ClickHouseColumn valueInfo = valueToColumnForDynamicType(entry.getValue());
            column = ClickHouseColumn.of("v", "Map(" + keyInfo.getOriginalTypeName() + ", " + valueInfo.getOriginalTypeName() + ")");
        } else if (value instanceof Enum<?>) {
            column = enumValue2Column((Enum)value);
        } else if (value instanceof List<?> || (value !=null && value.getClass().isArray())) {
            column = listValue2Column(value);
        } else if (value instanceof Instant) {
            column = ClickHouseColumn.of("v", "Time64(9)");
        } else if (value == null) {
            column = PREDEFINED_TYPE_COLUMNS.get(Void.class);
        } else {
            column = PREDEFINED_TYPE_COLUMNS.get(value.getClass());
        }

        if (column == null) {
            throw new ClientException("Unable to serialize value of " + value.getClass() + " because not supported yet");
        }

        return column;
    }
